<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Recruit/position_list')}" class="on">职位列表</a>|			<a href="{pigcms{:U('Recruit/position_category')}">职位分类管理</a>		</ul>	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/position_list')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="position_list"/>                    筛选: 					<if condition="$admin_area neq 3">						<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>					</if>                    <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="position_name" <if condition="$_GET['type'] eq 'position_name'">selected="selected"</if>>职位名称</option>                        <option value="company_name" <if condition="$_GET['type'] eq 'company_name'">selected="selected"</if>>企业名称</option>                        <option value="name" <if condition="$_GET['type'] eq 'name'">selected="selected"</if>>用户昵称</option>                    </select>                    <input type="submit" value="查询" class="button"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th>编号</th>						<th>企业名称</th>						<th>职位名称</th>						<th width="40%">职位描述</th>						<!-- <th>身份证号</th>						<th>地址</th>						<th>店铺面积</th> -->						<th>状态</th>						<th>申请时间</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list['list']">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.position_id}</td>								<td>{pigcms{$vo.company_name}</td>								<td>{pigcms{$vo.position_name}</td>								<td>{pigcms{$vo.desc}</td>								<!-- <td>{pigcms{$vo.phone}</td>								<td>{pigcms{$vo.card_id}</td>								<td>{pigcms{$vo.address}</td>								<td>{pigcms{$vo.acreage}</td> -->								<td>                                <if condition="$vo['status'] eq 0">                                	<span style="color: orange;">待审核</span>                                <elseif condition="$vo['status'] eq 1"/>                                	<span style="color: green;">审核通过</span>                                <elseif condition="$vo['status'] eq 2"/>                                	<span style="color: red;">审核不通过</span>                                </if>                            	</td>                                <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>								<td>									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('position_audit',array('position_id'=>$vo['position_id']))}','审核',600,500,true,false,false,editbtn,'edit',true);">审核</a>|									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.position_id}" url="{pigcms{:U('position_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="15">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="16">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>